package cn.binbin.crm;

import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.constraints.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.function.Function;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class PortalAuthService {
 public record AccountInput(@NotNull UUID customerId,@Email @NotBlank @Size(max=254) String email,@NotBlank @Size(max=100) String displayName,@NotBlank @Size(max=72) String initialPassword){}
 public record AccountEdit(@NotBlank @Size(max=100) String displayName,@NotNull @Pattern(regexp="ACTIVE|DISABLED") String status,boolean mustChangePassword,@Size(max=72) String newPassword,@Min(0) long expectedVersion){}
 public record LoginInput(@NotBlank @Pattern(regexp="[a-z0-9][a-z0-9_-]{1,39}") String tenantCode,@Email @NotBlank @Size(max=254) String email,@NotBlank @Size(max=72) String password){}
 public record PasswordInput(@NotBlank @Size(max=72) String oldPassword,@NotBlank @Size(max=72) String newPassword){}
 public record Context(UUID sessionId,UUID accountId,UUID tenantId,UUID customerId,String tenantCode,String tenantName,String brandName,String supportEmail,String email,String displayName,String csrf,Instant expiresAt,boolean mustChangePassword){}
 public record LoginResult(String token,Context context){}
 private final NamedParameterJdbcTemplate db;private final TransactionTemplate tx;private final AuthService auth;private final CustomerService customers;private final BCryptPasswordEncoder passwords=new BCryptPasswordEncoder(12);private final String dummy=passwords.encode("invalid-portal-"+UUID.randomUUID());private final long hours;
 public PortalAuthService(NamedParameterJdbcTemplate db,TransactionTemplate tx,AuthService auth,CustomerService customers,@Value("${crm.portal-session-hours:12}") long hours){this.db=db;this.tx=tx;this.auth=auth;this.customers=customers;this.hours=hours;}
 private static Map<String,Object> p(Object... v){return SaasService.parameters(v);}private static String text(String s){return s==null?"":s.strip();}
 private static Instant at(Map<String,Object> r,String key){return ((Timestamp)r.get(key)).toInstant();}
 private void context(UUID tenant){db.queryForObject("SELECT set_config('crm.tenant_id',:tenant,true)",Map.of("tenant",tenant.toString()),String.class);}
 private void audit(UUID tenant,UUID customer,UUID account,String action,String entity,UUID entityId,UUID trace){db.update("INSERT INTO portal_audit(id,tenant_id,customer_id,account_id,action,entity_type,entity_id,trace_id) VALUES(:id,:tenant,:customer,:account,:action,:entity,:entityId,:trace)",p("id",UUID.randomUUID(),"tenant",tenant,"customer",customer,"account",account,"action",action,"entity",entity,"entityId",entityId,"trace",trace));}
 private <T>T internal(AuthService.Session s,boolean write,Function<AuthService.Actor,T> fn){return tx.execute(st->{if(write&&s.tenantId()!=null)db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",Map.of("tenant",s.tenantId()),UUID.class);var a=auth.actor(s);if(a.supportGrantId()!=null||!a.p4Access().portalAccountManage())throw ApiError.forbidden("仅企业管理员可管理客户门户账号");if(!Boolean.TRUE.equals(db.queryForObject("SELECT p.portal_enabled FROM sys_tenant t JOIN sys_plan p ON p.id=t.plan_id WHERE t.id=:id",Map.of("id",a.tenant().id()),Boolean.class)))throw ApiError.forbidden("当前套餐未启用客户门户");if(write&&!a.tenant().subscriptionEnd().isAfter(Instant.now()))throw ApiError.forbidden("订阅到期，门户账号仅可查看");context(a.tenant().id());return fn.apply(a);});}
 public Object accounts(AuthService.Session s){return internal(s,false,a->db.queryForList("SELECT p.id,p.customer_id,c.customer_name,p.email,p.display_name,p.status,p.must_change_password,p.last_login_at,p.version,p.created_at,p.updated_at FROM portal_account p JOIN crm_customer c ON c.tenant_id=p.tenant_id AND c.id=p.customer_id WHERE p.tenant_id=:tenant ORDER BY p.updated_at DESC,p.id",Map.of("tenant",a.tenant().id())).stream().map(SaasService::view).toList());}
 public Object saveAccount(AuthService.Session s,UUID ignored,AccountInput i,String key,UUID trace){if(key==null||!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw ApiError.bad("请求编号无效");AuthService.validatePassword(i.initialPassword());return internal(s,true,a->{if(!customers.get(a,i.customerId()).canWrite()&&!a.admin())throw ApiError.forbidden("无权为该客户开通门户账号");String email=text(i.email()).toLowerCase(Locale.ROOT),requestHash=Crypto.hash(i.customerId()+":"+email+":"+text(i.displayName())+":"+Crypto.hash(i.initialPassword()));var request=p("scope",a.tenant().id().toString(),"user",s.userId(),"op","portal-account.create","key",key,"hash",requestHash);db.update("INSERT INTO sys_control_request(scope_key,user_id,operation,request_key,request_hash) VALUES(:scope,:user,:op,:key,:hash) ON CONFLICT DO NOTHING",request);var prior=db.queryForMap("SELECT request_hash,result_id FROM sys_control_request WHERE scope_key=:scope AND user_id=:user AND operation=:op AND request_key=:key FOR UPDATE",request);if(!requestHash.equals(prior.get("request_hash")))throw ApiError.conflict("相同请求编号对应的内容已变化");UUID id=(UUID)prior.get("result_id");if(id==null){if(db.queryForObject("SELECT count(*) FROM portal_account WHERE tenant_id=:tenant AND email_norm=:email",p("tenant",a.tenant().id(),"email",email),Integer.class)>0)throw ApiError.conflict("该邮箱已在本企业开通门户");id=UUID.randomUUID();db.update("INSERT INTO portal_account(id,tenant_id,customer_id,email,email_norm,display_name,password_hash,created_by_member_id) VALUES(:id,:tenant,:customer,:email,:email,:name,:hash,:member)",p("id",id,"tenant",a.tenant().id(),"customer",i.customerId(),"email",email,"name",text(i.displayName()),"hash",auth.passwordHash(i.initialPassword()),"member",a.tenant().memberId()));request.put("result",id);db.update("UPDATE sys_control_request SET result_id=:result WHERE scope_key=:scope AND user_id=:user AND operation=:op AND request_key=:key",request);DataService.audit(db,a,"PORTAL_ACCOUNT_CREATED","PORTAL_ACCOUNT",id,0,trace);}return SaasService.view(db.queryForMap("SELECT id,customer_id,email,display_name,status,must_change_password,version,created_at FROM portal_account WHERE tenant_id=:tenant AND id=:id",p("tenant",a.tenant().id(),"id",id)));});}
 public Object editAccount(AuthService.Session s,UUID id,AccountEdit i,UUID trace){if(i.newPassword()!=null&&!i.newPassword().isBlank())AuthService.validatePassword(i.newPassword());return internal(s,true,a->{var q=p("id",id,"tenant",a.tenant().id(),"name",text(i.displayName()),"status",i.status(),"must",i.mustChangePassword(),"version",i.expectedVersion());String password="";if(i.newPassword()!=null&&!i.newPassword().isBlank()){q.put("hash",auth.passwordHash(i.newPassword()));password=",password_hash=:hash,auth_version=auth_version+1";}if(db.update("UPDATE portal_account SET display_name=:name,status=:status,must_change_password=:must,version=version+1,updated_at=now()"+password+" WHERE tenant_id=:tenant AND id=:id AND version=:version",q)!=1)throw ApiError.conflict("门户账号已变化，请刷新");if(!i.status().equals("ACTIVE")||!password.isEmpty())db.update("UPDATE portal_session SET revoked_at=now() WHERE account_id=:id AND revoked_at IS NULL",p("id",id));DataService.audit(db,a,"PORTAL_ACCOUNT_UPDATED","PORTAL_ACCOUNT",id,i.expectedVersion()+1,trace);return SaasService.view(db.queryForMap("SELECT id,customer_id,email,display_name,status,must_change_password,last_login_at,version,updated_at FROM portal_account WHERE tenant_id=:tenant AND id=:id",p("tenant",a.tenant().id(),"id",id)));});}
 public LoginResult login(LoginInput i,UUID trace){if(i.password().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw ApiError.unauthorized();String code=text(i.tenantCode()).toLowerCase(Locale.ROOT),email=text(i.email()).toLowerCase(Locale.ROOT),limit=Crypto.hash("portal:"+code+":"+email);LoginResult result=tx.execute(st->{db.update("INSERT INTO portal_login_limit(key_hash) VALUES(:key) ON CONFLICT DO NOTHING",p("key",limit));var guard=db.queryForMap("SELECT * FROM portal_login_limit WHERE key_hash=:key FOR UPDATE",p("key",limit));Timestamp blocked=(Timestamp)guard.get("blocked_until");if(blocked!=null&&blocked.toInstant().isAfter(Instant.now()))return null;var found=db.queryForList("SELECT p.*,t.code AS tenant_code,t.name AS tenant_name,t.status AS tenant_status,t.subscription_end,sp.portal_enabled AS plan_portal_enabled FROM portal_account p JOIN sys_tenant t ON t.id=p.tenant_id JOIN sys_plan sp ON sp.id=t.plan_id WHERE t.code=:code AND p.email_norm=:email",p("code",code,"email",email));var row=found.isEmpty()?null:found.getFirst();boolean match=passwords.matches(i.password(),row==null?dummy:String.valueOf(row.get("password_hash")));if(row==null||!match||!"ACTIVE".equals(row.get("status"))||!"ACTIVE".equals(row.get("tenant_status"))||!Boolean.TRUE.equals(row.get("plan_portal_enabled"))||!at(row,"subscription_end").isAfter(Instant.now())){boolean old=((Timestamp)guard.get("updated_at")).toInstant().isBefore(Instant.now().minusSeconds(900));int failures=blocked!=null||old?1:((Number)guard.get("failures")).intValue()+1;db.update("UPDATE portal_login_limit SET failures=:failures,blocked_until=:blocked,updated_at=now() WHERE key_hash=:key",p("failures",failures,"blocked",failures>=5?Timestamp.from(Instant.now().plusSeconds(900)):null,"key",limit));return null;}UUID tenant=(UUID)row.get("tenant_id"),customer=(UUID)row.get("customer_id"),account=(UUID)row.get("id");context(tenant);var profile=db.queryForMap("SELECT * FROM sys_tenant_profile WHERE tenant_id=:tenant",p("tenant",tenant));if(!Boolean.TRUE.equals(profile.get("portal_enabled")))return null;db.update("UPDATE portal_login_limit SET failures=0,blocked_until=NULL,updated_at=now() WHERE key_hash=:key",p("key",limit));db.update("DELETE FROM portal_session WHERE account_id=:account AND(expires_at<now() OR revoked_at IS NOT NULL)",p("account",account));String token=Crypto.token(),csrf=Crypto.token();UUID session=UUID.randomUUID();Instant expires=Instant.now().plusSeconds(hours*3600);db.update("INSERT INTO portal_session(id,account_id,token_hash,csrf_token,account_auth_version,expires_at) VALUES(:id,:account,:hash,:csrf,:version,:expires)",p("id",session,"account",account,"hash",Crypto.hash(token),"csrf",csrf,"version",row.get("auth_version"),"expires",Timestamp.from(expires)));db.update("UPDATE portal_account SET last_login_at=now(),updated_at=now() WHERE id=:account",p("account",account));db.update("INSERT INTO sys_usage_monthly(tenant_id,usage_month,portal_logins) VALUES(:tenant,date_trunc('month',current_date)::date,1) ON CONFLICT(tenant_id,usage_month) DO UPDATE SET portal_logins=sys_usage_monthly.portal_logins+1,updated_at=now()",p("tenant",tenant));audit(tenant,customer,account,"LOGIN_SUCCEEDED","PORTAL_SESSION",session,trace);return new LoginResult(token,new Context(session,account,tenant,customer,String.valueOf(row.get("tenant_code")),String.valueOf(row.get("tenant_name")),String.valueOf(profile.get("brand_name")),String.valueOf(profile.get("support_email")),String.valueOf(row.get("email")),String.valueOf(row.get("display_name")),csrf,expires,Boolean.TRUE.equals(row.get("must_change_password"))));});if(result==null)throw new ApiError(org.springframework.http.HttpStatus.UNAUTHORIZED,"PORTAL_LOGIN_FAILED","企业代码、邮箱或密码错误，请稍后重试");return result;}
 public Context authenticate(HttpServletRequest request){String token=null;if(request.getCookies()!=null)for(Cookie c:request.getCookies())if("CRM_PORTAL_SESSION".equals(c.getName()))token=c.getValue();if(token==null||!token.matches("[A-Za-z0-9_-]{43}"))throw ApiError.unauthorized();var rows=db.queryForList("SELECT s.*,p.tenant_id,p.customer_id,p.email,p.display_name,p.must_change_password,t.code AS tenant_code,t.name AS tenant_name,t.status AS tenant_status,t.subscription_end,sp.portal_enabled AS plan_portal_enabled FROM portal_session s JOIN portal_account p ON p.id=s.account_id JOIN sys_tenant t ON t.id=p.tenant_id JOIN sys_plan sp ON sp.id=t.plan_id WHERE s.token_hash=:hash AND s.revoked_at IS NULL AND s.expires_at>now() AND p.status='ACTIVE' AND p.auth_version=s.account_auth_version",p("hash",Crypto.hash(token)));if(rows.isEmpty())throw ApiError.unauthorized();var r=rows.getFirst();if(!"ACTIVE".equals(r.get("tenant_status"))||!Boolean.TRUE.equals(r.get("plan_portal_enabled"))||!at(r,"subscription_end").isAfter(Instant.now()))throw ApiError.unauthorized();UUID tenant=(UUID)r.get("tenant_id");return tx.execute(st->{context(tenant);var profile=db.queryForList("SELECT * FROM sys_tenant_profile WHERE tenant_id=:tenant AND portal_enabled",p("tenant",tenant));if(profile.isEmpty())throw ApiError.unauthorized();var x=profile.getFirst();return new Context((UUID)r.get("id"),(UUID)r.get("account_id"),tenant,(UUID)r.get("customer_id"),String.valueOf(r.get("tenant_code")),String.valueOf(r.get("tenant_name")),String.valueOf(x.get("brand_name")),String.valueOf(x.get("support_email")),String.valueOf(r.get("email")),String.valueOf(r.get("display_name")),String.valueOf(r.get("csrf_token")),at(r,"expires_at"),Boolean.TRUE.equals(r.get("must_change_password")));});}
 public void csrf(Context c,HttpServletRequest r){if(!Crypto.same(c.csrf(),r.getHeader("X-CSRF-Token")))throw ApiError.forbidden("请求校验失败，请刷新门户登录状态");}
 public Object view(Context c){return p("account",p("id",c.accountId(),"email",c.email(),"displayName",c.displayName(),"mustChangePassword",c.mustChangePassword()),"tenant",p("code",c.tenantCode(),"name",c.tenantName(),"brandName",c.brandName(),"supportEmail",c.supportEmail()),"csrfToken",c.csrf(),"expiresAt",c.expiresAt());}
 public void logout(Context c,UUID trace){tx.executeWithoutResult(st->{db.update("UPDATE portal_session SET revoked_at=now() WHERE id=:id",p("id",c.sessionId()));audit(c.tenantId(),c.customerId(),c.accountId(),"LOGOUT","PORTAL_SESSION",c.sessionId(),trace);});}
 public void password(Context c,PasswordInput i,UUID trace){AuthService.validatePassword(i.newPassword());if(i.oldPassword().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw ApiError.bad("原密码长度无效");tx.executeWithoutResult(st->{var r=db.queryForMap("SELECT password_hash FROM portal_account WHERE id=:id FOR UPDATE",p("id",c.accountId()));if(!passwords.matches(i.oldPassword(),String.valueOf(r.get("password_hash"))))throw ApiError.forbidden("原密码不正确");if(Crypto.same(i.oldPassword(),i.newPassword()))throw ApiError.bad("新密码不能与原密码相同");db.update("UPDATE portal_account SET password_hash=:hash,must_change_password=false,auth_version=auth_version+1,version=version+1,updated_at=now() WHERE id=:id",p("hash",passwords.encode(i.newPassword()),"id",c.accountId()));db.update("UPDATE portal_session SET revoked_at=now() WHERE account_id=:id",p("id",c.accountId()));audit(c.tenantId(),c.customerId(),c.accountId(),"PASSWORD_CHANGED","PORTAL_ACCOUNT",c.accountId(),trace);});}
 public void audit(Context c,String action,String type,UUID id,UUID trace){audit(c.tenantId(),c.customerId(),c.accountId(),action,type,id,trace);}
}
